mapper.select:
SELECT m.*, u_sender.username AS senderName, u_receiver.username AS receiverName FROM messages m LEFT JOIN users u_sender ON m.sender_id = u_sender.id LEFT JOIN users u_receiver ON m.receiver_id = u_receiver.id WHERE ( (m.sender_id = #{userId} AND m.receiver_id = #{otherUserId}) OR (m.sender_id = #{otherUserId} AND m.receiver_id = #{userId}) )
AND m.product_id = #{productId}
ORDER BY m.created_at ASC

mapper.update:
UPDATE messages SET is_read = 1
WHERE sender_id = #{senderId}
  AND receiver_id = #{receiverId}

  AND product_id = #{productId}

  AND is_read = 0

